positional:
// Use the engine's official setter paths everywhere
setup.applyAndNotifyFlag('player', null, 'frank_cracked', 'set');
setup.applyAndNotifyFlag('player', null, 'frank_restrict_declared', 'set');
setup.applyAndNotifyFlag('player', null, 'frank_office_first_sex_done', 'set');
setup.applyAndNotifyFlag('player', null, 'frank_invited_to_bedroom', 'unset');
setup.applyAndNotifyFlag('player', null, 'talked_to_frank_today', 'unset');
// Force frank_office_visits to 3 — set via direct assignment since 'add' wouldn't reach 3 in one go
setup.applyAndNotifyTrait('player', null, 'frank_office_visits', 'add', 3, false, null);
// Force Frank.corruption to 25
var frankUuid = null;
for (var k in SugarCube.State.variables.npcs) { if (SugarCube.State.variables.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
if (frankUuid) {
  setup.applyAndNotifyTrait('npc', frankUuid, 'corruption', 'add', 25, false, null);
}
'state set'

var sv = SugarCube.State.variables;
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
var probe = {
  visits: sv.player.core_traits.frank_office_visits,
  frank_corr: frankUuid ? sv.npcs[frankUuid].core_traits.corruption : 'NO_UUID',
  flag_first_sex: sv.player.flagBag && sv.player.flagBag.frank_office_first_sex_done,
  flag_invited: sv.player.flagBag && sv.player.flagBag.frank_invited_to_bedroom,
  flag_cracked: sv.player.flagBag && sv.player.flagBag.frank_cracked,
  flag_restrict: sv.player.flagBag && sv.player.flagBag.frank_restrict_declared,
  flag_talked: sv.player.flagBag && sv.player.flagBag.talked_to_frank_today,
  stage: sv.player.core_traits.npc_frank_stage,
  cap1_first_sex_check: setup.checkSingleCondition({type:'flag', subject:'player', flag_key:'frank_office_first_sex_done', operator:'is_true'}),
  cap2_invited_check: setup.checkSingleCondition({type:'flag', subject:'player', flag_key:'frank_invited_to_bedroom', operator:'is_false'}),
  cap3_corr_check: setup.checkSingleCondition({type:'trait', subject:'npc', npc_id:'npc_frank', trait_key:'corruption', operator:'gte', value:25}),
  cap4_visits_check: setup.checkSingleCondition({type:'trait', subject:'player', trait_key:'frank_office_visits', operator:'gte', value:3}),
};
document.title = 'P:' + JSON.stringify(probe);
'set'

var sv = SugarCube.State.variables;
var frankUuid = null;
for (var k in sv.npcs) { if (sv.npcs[k].slug === 'npc_frank') { frankUuid = k; break; } }
// Direct writes — bypass the setter quirks
sv.npcs[frankUuid].core_traits.corruption = 25;
sv.player.core_traits.frank_office_visits = 3;
sv.player.flagBag = sv.player.flagBag || {};
sv.player.flagBag.frank_office_first_sex_done = true;
sv.player.flagBag.frank_invited_to_bedroom = false;
sv.player.flagBag.frank_cracked = true;
sv.player.flagBag.frank_restrict_declared = true;
sv.player.flagBag.talked_to_frank_today = false;
SugarCube.Engine.play('Canvas_scene_office_after_crack_Node_1');
'set'

